// @name JSX: Now playing
// @background #000000
// @refresh 1
// A player: play and pause, skip back and forward, and drag the bar to seek.
// The cover is a gradient and an SVG; the bar moves with the clock while it
// plays, and follows the finger while it is held (a captured press).
// `at` (a field) pins the time, for a snapshot; empty, it is the clock.
const tracks = [
  { title: 'Log Cabin Lullaby', artist: 'The Forest Choir', length: 201, cover: 'from-fuchsia-500 to-indigo-800', bg: 'bg-fuchsia-950' },
  { title: 'Northern Lights', artist: 'Aurora Static', length: 244, cover: 'from-emerald-300 to-cyan-800', bg: 'bg-emerald-950' },
  { title: 'Paper Boats', artist: 'Juniper Lane', length: 187, cover: 'from-amber-300 to-rose-600', bg: 'bg-rose-950' },
  { title: 'Night Bus Home', artist: 'Metro Hum', length: 222, cover: 'from-sky-400 to-slate-800', bg: 'bg-sky-950' },
]

let index = 0
let playing = true
let offset = 74 // seconds played when the clock started
let since = null
let clockAt = () => Date.now()

const position = () => {
  const t = offset + (playing ? (clockAt() - since) / 1000 : 0)
  return t % tracks[index].length
}
const toggle = () => {
  offset = position(); since = clockAt(); playing = !playing
}
const skip = (by) => {
  index = (index + by + tracks.length) % tracks.length; offset = 0; since = clockAt()
}
// The seek bar's width: the UI's less the page's px-8 on both sides, set by
// each render for the handlers that run before the next.
let barW = 480 - 64
const seek = (e) => {
  const fraction = Math.max(0, Math.min(1, e.localX / barW))
  offset = fraction * tracks[index].length; since = clockAt()
}
const clock = (s) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`

const Icon = ({ d, className }) => (
  <svg className={className} viewBox="0 0 24 24"><path fill="currentColor" d={d} /></svg>
)

// The size the UI is laid out at: the image it draws into, else the frame
// as the scene sees it (app.frame is the panel's, before the turn).
const uiSize = (app, context) => {
  const turned = [90, 270].includes(app.frame.rotate)
  return [context?.imageWidth ?? (turned ? app.frame.height : app.frame.width),
    context?.imageHeight ?? (turned ? app.frame.width : app.frame.height)]
}

export function get(app, context) {
  barW = uiSize(app, context)[0] - 64
  if (app.config.at) clockAt = () => Date.parse(app.config.at)
  if (since === null) since = clockAt()
  const track = tracks[index]
  const at = position()
  return (
    <div className={`flex flex-col items-center gap-4 px-8 py-6 ${track.bg} text-white`}>
      <span className="text-xs uppercase text-white/60 font-semibold">{`Track ${index + 1} of ${tracks.length}`}</span>
      <div className={`w-44 h-44 rounded-3xl bg-gradient-to-br ${track.cover} flex items-center justify-center`}>
        <svg className="w-24 h-24 text-white/70" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round">
          <circle cx={12} cy={12} r={10} />
          <circle cx={12} cy={12} r={6} />
          <circle cx={12} cy={12} r={2} fill="currentColor" />
        </svg>
      </div>
      <div className="flex flex-col items-center w-full">
        <span className="text-2xl font-bold truncate">{track.title}</span>
        <span className="text-white/70">{track.artist}</span>
      </div>
      <div className="flex flex-col w-full gap-1">
        <div className="flex items-center h-8" onPointerDown={seek} onPointerMove={seek}>
          <div className="flex-1 h-1 rounded-full bg-white/20">
            <div className={`flex items-center justify-end h-1 rounded-full bg-white w-[${Math.max(2, Math.round((at * barW) / track.length))}px]`}>
              <div className="w-3 h-3 -mr-1 rounded-full bg-white" />
            </div>
          </div>
        </div>
        <div className="flex justify-between text-xs text-white/60">
          <span>{clock(at)}</span>
          <span>{clock(track.length)}</span>
        </div>
      </div>
      <div className="flex items-center justify-between w-full px-6">
        <div className="w-16 h-16 rounded-full flex items-center justify-center active:bg-white/20" onClick={() => skip(-1)}>
          <Icon className="w-9 h-9 text-white/80" d="M6 6h2v12H6zM9.5 12l8.5 6V6z" />
        </div>
        <div className="w-20 h-20 rounded-full bg-white flex items-center justify-center active:bg-white/60" onClick={toggle}>
          <Icon className="w-10 h-10 text-black" d={playing ? 'M6 4h4v16H6zM14 4h4v16h-4z' : 'M7 4v16l13-8z'} />
        </div>
        <div className="w-16 h-16 rounded-full flex items-center justify-center active:bg-white/20" onClick={() => skip(1)}>
          <Icon className="w-9 h-9 text-white/80" d="M16 6h2v12h-2zM6 18l8.5-6L6 6z" />
        </div>
      </div>
    </div>
  )
}
